import{c as p,Q as a,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const e="data:image/png;base64,",o="/assets/%E5%8D%B7%E7%A7%AF%E5%B1%82%E7%9A%84%E5%89%8D%E5%90%8E%E5%90%91%E4%BC%A0%E6%92%AD%E7%A4%BA%E6%84%8F%E5%9B%BE.C29c1OBK.png",i="/assets/%E5%8F%8D%E5%90%91%E4%BC%A0%E6%92%AD%E8%AF%AF%E5%B7%AE%E8%AE%A1%E7%AE%97%E7%A4%BA%E6%84%8F%E5%9B%BE.CRXjIyB4.png",C=JSON.parse('{"title":"Conv3DBackpropInput使用说明","description":"","frontmatter":{},"headers":[{"level":1,"title":"Conv3DBackpropInput使用说明","slug":"conv3dbackpropinput使用说明"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件"}],"relativePath":"api/SIMD-API/高阶API/卷积计算/Conv3DBackpropInput/Conv3DBackpropInput-Kernel侧接口/Conv3DBackpropInput使用说明.md","filePath":"api/SIMD-API/高阶API/卷积计算/Conv3DBackpropInput/Conv3DBackpropInput-Kernel侧接口/Conv3DBackpropInput使用说明.md"}'),l={name:"api/SIMD-API/高阶API/卷积计算/Conv3DBackpropInput/Conv3DBackpropInput-Kernel侧接口/Conv3DBackpropInput使用说明.md"};function c(d,t,r,g,u,A){return a(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="conv3dbackpropinput使用说明" tabindex="-1">Conv3DBackpropInput使用说明 <a class="header-anchor" href="#conv3dbackpropinput使用说明" aria-label="Permalink to &quot;Conv3DBackpropInput使用说明&quot;">​</a></h1><p>Ascend C提供一组Conv3DBackpropInput高阶API，便于用户快速实现卷积的反向运算，求解反向传播的误差。转置卷积Conv3DTranspose与Conv3DBackpropInput具有相同的数学过程，因此用户也可以使用Conv3DBackpropInput高阶API实现转置卷积算子。卷积的正反向传播如<a href="#fig1069918872512">图1 卷积层的前后向传播示意图</a>，反向传播误差计算如<a href="#fig1953483815252">图2 反向传播误差计算示意图</a>。</p><p>Conv3DBackpropInput的计算公式为：</p><p><img src="'+e+'" alt=""></p><ul><li>∂L/∂Y为卷积正向损失函数对输出Y的梯度GradOutput，作为求反向传播误差∂L/∂X的输入。</li><li>W为卷积正向Weight权重，即矩阵核Kernel，也是滤波器Filter，作为求反向传播误差∂L/∂X的输入，WT表示W的转置。</li><li>∂L/∂X为特征矩阵的反向传播误差GradInput。</li></ul><p><strong>图 1</strong> 卷积层的前后向传播示意图<br><img src="'+o+'" alt="" title="卷积层的前后向传播示意图"></p><p><strong>图 2</strong> 反向传播误差计算示意图<br><img src="'+i+`" alt="" title="反向传播误差计算示意图"></p><p>Kernel侧实现Conv3DBackpropInput求解反向传播误差运算的步骤概括为：</p><ol><li><p>创建Conv3DBackpropInput对象。</p></li><li><p>初始化操作。</p></li><li><p>设置卷积的输出反向GradOutput、卷积的输入Weight。</p></li><li><p>完成卷积反向操作。</p></li><li><p>结束卷积反向操作。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>下文中提及的M轴方向，即为GradOutput矩阵纵向；K轴方向，即为GradOutput矩阵横向或Weight矩阵纵向；N轴方向，即为Weight矩阵横向。</p></div></li></ol><p>使用Conv3DBackpropInput高阶API求解反向传播误差运算的具体步骤如下：</p><ol><li><p>创建Conv3DBackpropInput对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/conv_backprop/conv3d_bp_input_api.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using weightDxType = ConvBackpropApi::ConvType&lt;ConvCommonApi::TPosition::GM, ConvCommonApi::ConvFormat::FRACTAL_Z_3D, weightType&gt;;</span></span>
<span class="line"><span>using inputSizeDxType =	ConvBackpropApi::ConvType&lt;ConvCommonApi::TPosition::GM, ConvCommonApi::ConvFormat::ND, int32_t&gt;;</span></span>
<span class="line"><span>using gradOutputDxType = ConvBackpropApi::ConvType&lt;ConvCommonApi::TPosition::GM, ConvCommonApi::ConvFormat::NDC1HWC0, gradOutputType&gt;;</span></span>
<span class="line"><span>using gradInputDxType = ConvBackpropApi::ConvType&lt;ConvCommonApi::TPosition::GM, ConvCommonApi::ConvFormat::NCDHW, gradInputType&gt;;</span></span>
<span class="line"><span>ConvBackpropApi::Conv3DBackpropInput&lt;weightDxType, inputSizeDxType, gradOutputDxType, gradInputDxType&gt; gradInput_;</span></span></code></pre></div><p>创建对象时需要传入权重矩阵Weight、卷积正向特征矩阵Input的shape信息InputSize、GradOutput和GradInput的参数类型信息，类型信息通过<a href="#table19081115275">ConvType</a>来定义，包括：内存逻辑位置、数据格式、数据类型。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;TPosition POSITION, ConvFormat FORMAT, typename T&gt;</span></span>
<span class="line"><span>struct ConvType {</span></span>
<span class="line"><span>    constexpr static TPosition pos = POSITION;    // Convolution输入或输出的逻辑位置</span></span>
<span class="line"><span>    constexpr static ConvFormat format = FORMAT;  // Convolution输入或输出的数据格式</span></span>
<span class="line"><span>    using Type = T;                               // Convolution输入或输出的数据类型</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>下面简要介绍在创建对象时使用到的相关数据结构，开发者可选择性地了解这些内容。用于创建Conv3DBackpropInput对象的数据结构定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using Conv3DBackpropInput = Conv3DBpInputIntf&lt;Conv3DBpInputCfg&lt;WEIGHT_TYPE, INPUT_TYPE, GRAD_OUTPUT_TYPE, GRAD_INPUT_TYPE, CONV3D_CFG_DEFAULT&gt;, Conv3DBpInputImpl&gt;;</span></span></code></pre></div><p>其中，Conv3DBpInputIntf、Conv3DBpInputCfg数据结构定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class Config_, template &lt;typename, class&gt; class Impl&gt;</span></span>
<span class="line"><span>struct Conv3DBpInputIntf {</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class WEIGHT_TYPE, class INPUT_TYPE, class GRAD_OUTPUT_TYPE, class GRAD_INPUT_TYPE, const Conv3dConfig&amp; CONV3D_CONFIG = CONV3D_CFG_DEFAULT&gt;</span></span>
<span class="line"><span>struct Conv3DBpInputCfg : public ConvBpContext&lt;WEIGHT_TYPE, INPUT_TYPE, GRAD_OUTPUT_TYPE, GRAD_INPUT_TYPE&gt; {</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>表 1</strong> ConvType说明</p></li></ol><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>POSITION</td><td>内存逻辑位置。 Weight矩阵可设置为TPosition::GMGradOutput矩阵可设置为TPosition::GMInputSize可设置为TPosition::GMGradInput矩阵可设置为TPosition::GM</td></tr><tr><td>ConvFormat</td><td>数据格式。 Weight矩阵可设置为ConvFormat::FRACTAL_Z_3DGradOutput矩阵可设置为ConvFormat::NDC1HWC0InputSize矩阵可设置为ConvFormat::NDGradInput矩阵可设置为ConvFormat::NDC1HWC0</td></tr><tr><td>TYPE</td><td>数据类型。Weight矩阵可设置为half、bfloat16_tGradOutput矩阵可设置为half、bfloat16_tInputSize矩阵可设置为int32_tGradInput矩阵可设置为half、bfloat16_t 注意：GradOutput矩阵和Weight矩阵数据类型需要一致，具体数据类型组合关系请参考表2。</td></tr></tbody></table><pre><code>**表 2**  Conv3DBackpropInput输入输出数据类型的组合说明
</code></pre><table tabindex="0"><thead><tr><th>Weight</th><th>GradOutput</th><th>InputSize</th><th>GradInput</th><th>支持平台</th></tr></thead><tbody><tr><td>half</td><td>half</td><td>int32_t</td><td>half</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr><td>bfloat16_t</td><td>bfloat16_t</td><td>int32_t</td><td>bfloat16_t</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr></tbody></table><ol start="2"><li><p>初始化操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 注册后进行初始化</span></span>
<span class="line"><span>ConvBackpropApi::Conv3DBackpropInput&lt;weightDxType, inputSizeDxType, gradOutputDxType, gradInputDxType&gt; gradInput_;</span></span>
<span class="line"><span>gradInput_.Init(&amp;(tilingData-&gt;conv3DDxTiling));</span></span></code></pre></div></li><li><p>设置3D卷积的输出反向GradOutput、3D卷积的输入Weight。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradInput_.SetSingleShape(singleShapeM_, singleShapeK_, singleShapeN_); // 设置单核计算的形状</span></span>
<span class="line"><span>gradInput_.SetStartPosition(dinStartIdx_, curHoStartIdx_); // 设置单核上gradOutput载入的起始位置</span></span>
<span class="line"><span>gradInput_.SetGradOutput(gradOutputGm_[offsetA_]);</span></span>
<span class="line"><span>gradInput_.SetWeight(weightGm_[offsetB_]);</span></span></code></pre></div></li><li><p>完成卷积反向操作。</p><p>调用<a href="./Iterate-111.html">Iterate</a>完成单次迭代计算，叠加while循环完成单核全量数据的计算。Iterate方式，可以自行控制迭代次数，完成所需数据量的计算。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (gradInput_.Iterate()) {</span></span>
<span class="line"><span>    gradInput_.GetTensorC(gradInputGm_[offsetC_]); </span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>结束卷积反向操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradInput_.End();</span></span></code></pre></div></li></ol><h2 id="需要包含的头文件" tabindex="-1">需要包含的头文件 <a class="header-anchor" href="#需要包含的头文件" aria-label="Permalink to &quot;需要包含的头文件&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/conv_backprop/conv3d_bp_input_api.h&quot;</span></span></code></pre></div>`,17)])])}const h=p(l,[["render",c]]);export{C as __pageData,h as default};
